package com.stayflow.customer.ui;
import android.content.Intent;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.stayflow.customer.data.*;import com.stayflow.customer.model.Models.*;import retrofit2.*;import retrofit2.Response;
public class ProfileActivity extends AppCompatActivity {public void onCreate(Bundle b){super.onCreate(b);SessionManager s=new SessionManager(this);LinearLayout p=Ui.page(this,"Customer Profile");Ui.text(this,p,s.email());EditText old=Ui.input(this,p,"Current password"),fresh=Ui.input(this,p,"New password");Ui.button(this,p,"Change password").setOnClickListener(v->ApiClient.create(this).changePassword(new PasswordRequest(old.getText().toString(),fresh.getText().toString())).enqueue(new Callback<Resp<Object>>(){public void onResponse(Call<Resp<Object>> c,Response<Resp<Object>> r){Ui.toast(ProfileActivity.this,r.isSuccessful()?"Password changed":"Unable to change password");}public void onFailure(Call<Resp<Object>> c,Throwable t){Ui.toast(ProfileActivity.this,t.getMessage());}}));Ui.button(this,p,"Sign out").setOnClickListener(v->{s.clear();startActivity(new Intent(this,LoginActivity.class));finishAffinity();});setContentView(new ScrollView(this){{addView(p);}});}}
